contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to attempt wagering (must equal currentBetLimit to succeed) and some ether funding for this test.
    function run(uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(true);

        // Ensure this contract has enough balance to send wagerAmount when attempting wager
        // The harness can send ETH to this call; require ensures we have it if we will use it.
        require(address(this).balance >= wagerAmount);

        // Read observable pre-state
        uint256 beforeBalance = address(c).balance;
        uint256 currentBet = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        bool hadWagerBefore = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // Attempt to place a wager with exactly wagerAmount. This is a top-level state-changing call.
        bool wagerReverted;
        c.wager{value: wagerAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // Attempt to call play(). This is a top-level state-changing call.
        bool playReverted;
        c.play(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            playReverted = true;
        } else {
            playReverted = false;
        }

        // Read observable post-state
        uint256 afterBalance = address(c).balance;
        bool hasWagerAfter = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        uint256 winnersPotAfter = c.winnersPot(); if (__ESBMC_reverted()) return;

        // Assert the general rule: if play() succeeded and this contract had just successfully wagered (i.e., wager did not revert
        // and before it did not have an active wager), then after play() the contract must have no active wager for this caller
        // and winnersPot equals half of the contract balance. We allow anything else if wager or play reverted or if the caller
        // already had a wager beforehand.
        assert(
            wagerReverted || playReverted || hadWagerBefore || (!hasWagerAfter && winnersPotAfter * 2 == afterBalance)
        );
    }

    // Allow receiving ETH to fund wagers
    receive() external payable {}
}

