        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        vm.assume(address(this).balance >= wagerAmount);
        uint256 beforeBalance = address(c).balance;
        uint256 currentBet;
        try c.currentBetLimit() returns (uint256 __r) { currentBet = __r; } catch { return; }
