        try c.wager{value: wagerAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }
        uint256 afterBalance = address(c).balance;
        bool hasWagerAfter;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { hasWagerAfter = __r; } catch { return; }
